import {editorialContent,homeModuleLabels} from './editorial-model.mjs?v=20261116usernames';
import {editorialEditor} from './admin-editors.mjs?v=20261116usernames';
import {e,safeURL,money} from './ui.mjs?v=20261116usernames';
import {validateContent,moduleTypes} from './content-validation.mjs?v=20261116usernames';
const config=window.CONFORT4_FORMS,base=config.endpoint.split('/functions/')[0],endpoint=config.endpoint.replace('confort4-forms','confort4-site');
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
let session=null,state=null,draft=null,tab='home',offset=0,unsaved=false,pending=false;
try{session=JSON.parse(sessionStorage.getItem('confort4-session'));}catch{}
const labels={vender:'Vender',rentar:'Rentar',comprar:'Comprar',home:'Pantalla principal',team:'Quiénes somos',services:'Servicios',process:'Proceso',faq:'Preguntas frecuentes',posts:'Blog',checklists:'Checklists',leads:'Contactos',reviews:'Reseñas',inventory:'Propiedades',media:'Imágenes',settings:'Configuración',versions:'Versiones'};
const moduleLabels=homeModuleLabels;
function normalizedSession(data){return {...data,editor_username:data.editor_username||session?.editor_username,expires_at:data.expires_at||Math.floor(Date.now()/1000)+(data.expires_in||3600)};}
function persist(){if(session)sessionStorage.setItem('confort4-session',JSON.stringify(session));else sessionStorage.removeItem('confort4-session');}
async function auth(path,body,token,method='POST'){const res=await fetch(base+'/auth/v1/'+path,{method,headers:{apikey:config.publishableKey,'Content-Type':'application/json',...(token?{Authorization:'Bearer '+token}:{})},body:JSON.stringify(body),signal:AbortSignal.timeout(15000)});const data=await res.json().catch(()=>({}));if(!res.ok)throw Error('No pudimos validar tu acceso. Revisa los datos e intenta de nuevo.');return data;}
async function api(action,args={}){
 if(!session)throw Error('Inicia sesión.');
 if(session.expires_at*1000<Date.now()+60000){session=normalizedSession(await auth('token?grant_type=refresh_token',{refresh_token:session.refresh_token}));persist();}
 const res=await fetch(endpoint,{method:'POST',headers:{apikey:config.publishableKey,Authorization:'Bearer '+session.access_token,'Content-Type':'application/json'},body:JSON.stringify({action,args}),signal:AbortSignal.timeout(25000)});
 const data=await res.json().catch(()=>({}));if(!res.ok){const error=Error(data.error||'No se pudo completar la operación.');error.code=data.code;throw error;}return data;
}
function status(text,error=false){const el=$('#admin-status')||$('#mfa-form [role=status]')||$('#login-status');el.textContent=text;el.classList.toggle('is-error',error);}
function at(path){return path.split('.').reduce((v,k)=>v?.[k],draft);}
function set(path,value){if(path.split('.').some(k=>['__proto__','prototype','constructor'].includes(k)))throw Error('Campo no permitido.');const keys=path.split('.'),last=keys.pop();keys.reduce((v,k)=>v[k],draft)[last]=value;}
function collect(){ $$('[data-bind]').forEach(el=>{const value=el.dataset.number!==undefined?Number(el.value):el.type==='checkbox'?el.checked:el.dataset.lines!==undefined?el.value.split('\n').map(t=>t.trim()).filter(Boolean):el.value;set(el.dataset.bind,value);}); }
function input(path,label,options={}){const value=at(path);if(options.choices)return `<label>${e(label)}<select data-bind="${e(path)}">${Object.entries(options.choices).map(([key,text])=>`<option value="${e(key)}" ${value===key?'selected':''}>${e(text)}</option>`).join('')}</select></label>`;if(options.check)return `<label class="consent"><input type="checkbox" data-bind="${path}" ${value?'checked':''}><span>${e(label)}</span></label>`;return `<label>${e(label)}${options.area||options.lines?`<textarea rows="${options.lines?4:3}" data-bind="${path}" ${options.lines?'data-lines':''}>${e(options.lines?(value||[]).join('\n'):value)}</textarea>`:`<input data-bind="${path}" value="${e(value)}" ${options.number?'type="number" data-number min="0" max="1000000"':options.type?'type="'+options.type+'"':''}>`}</label>`;}
function block(title,body){return `<section class="admin-block"><h3>${e(title)}</h3>${body}</section>`;}
function editor(){
 const enhanced=editorialEditor(tab,draft,{input,block});if(enhanced!==null)return enhanced;
 if(['services','vender','rentar','comprar'].includes(tab))return draft.services.map((s,i)=>({s,i})).filter(({s})=>tab==='services'||s.id===tab).map(({s,i})=>block(s.shortTitle,input(`services.${i}.title`,'Título')+input(`services.${i}.intro`,'Introducción',{area:true})+input(`services.${i}.image`,'URL de imagen')+input(`services.${i}.cta`,'Texto del botón')+input(`services.${i}.buttonHref`,'Destino del botón HTTPS o página interna')+s.sections.map((_,j)=>block('Contenido '+(j+1),input(`services.${i}.sections.${j}.title`,'Encabezado')+input(`services.${i}.sections.${j}.text`,'Texto',{area:true}))).join('')+(s.audiences||[]).map((a,j)=>block(a.title,input(`services.${i}.audiences.${j}.title`,'Encabezado')+input(`services.${i}.audiences.${j}.intro`,'Presentación',{area:true})+input(`services.${i}.audiences.${j}.items`,'Puntos · uno por línea',{lines:true}))).join('')+input(`services.${i}.closingTitle`,'Título del cierre')+input(`services.${i}.closing`,'Cierre',{area:true})+input(`services.${i}.closingButtonLabel`,'Texto del botón final')+input(`services.${i}.closingButtonHref`,'Destino del botón final'))).join('');
 if(tab==='checklists')return Object.keys(draft.checklists).map(key=>block({venta:'Vender',visita:'Visita',renta:'Renta'}[key],input('checklists.'+key,'Puntos · uno por línea',{lines:true}))).join('');
 if(tab==='posts')return '<p>Los artículos nuevos aparecen en el blog al publicar. Desmarca «Visible» para retirarlos de la página.</p><button class="button button-outline" data-new-post>Crear artículo</button>'+draft.posts.map((p,i)=>`<details class="admin-post"><summary>${e(p.title)} · ${p.published?'Visible':'Oculto'}</summary>${input(`posts.${i}.title`,'Título')+input(`posts.${i}.slug`,'Identificador URL · minúsculas y guiones')+input(`posts.${i}.category`,'Tema')+input(`posts.${i}.excerpt`,'Descripción breve',{area:true})+input(`posts.${i}.cover`,'URL de portada')+input(`posts.${i}.author`,'Autor')+input(`posts.${i}.updated`,'Fecha de actualización',{type:'date'})+input(`posts.${i}.published`,'Visible en la página',{check:true})+input(`posts.${i}.summary`,'En pocas palabras · un punto por línea',{lines:true})}${p.sections.map((s,j)=>block('Sección '+(j+1),input(`posts.${i}.sections.${j}.title`,'Título de sección')+input(`posts.${i}.sections.${j}.text`,'Contenido',{area:true})+`<button class="text-button" data-delete-section="${i},${j}">Eliminar sección</button>`)).join('')}<button class="text-button" data-new-section="${i}">Agregar sección</button>${p.source?input(`posts.${i}.source.label`,'Nombre de fuente')+input(`posts.${i}.source.url`,'URL HTTPS de fuente'):''}<button class="text-button danger" data-delete-post="${i}">Eliminar artículo del borrador</button></details>`).join('');
 return '';
}
function editorNavigation(){
 const buttons=keys=>keys.map(key=>`<button data-tab="${key}" ${tab===key?'aria-current="page"':''}>${e(labels[key])}</button>`).join('');
 return buttons(['home','team'])+'<div class="admin-nav-group"><span>Me interesa</span>'+buttons(['vender','rentar','comprar'])+'</div>'+buttons(['inventory','reviews','posts'])+'<div class="admin-nav-group"><span>Administración</span>'+buttons(['leads','media','settings','versions'])+'</div>';
}
function shell(){
 const opened=new Set($$('details[open]',$('#admin-panel')).map(element=>$('summary',element)?.textContent));
 $('.admin-login').hidden=true;$('#admin-panel').hidden=false;
 $('#admin-panel').innerHTML=`<div class="admin-shell"><aside class="admin-sidebar"><strong>Confort4 · equipo</strong><p>${e(session.editor_username||session.user?.user_metadata?.editor_username||'Cuenta autorizada')}<br>Rol: ${e(state.role)}</p><nav aria-label="Panel administrativo">${editorNavigation()}</nav><button class="text-button" id="logout">Cerrar sesión</button></aside><div class="admin-workspace"><header class="admin-toolbar"><div><h2>${labels[tab]}</h2><p id="revision">${unsaved?'Cambios sin guardar':'Borrador · versión '+state.revision}</p></div><div class="admin-actions"><button class="button button-outline" id="preview">Vista previa</button><button class="button button-outline" id="save">Guardar borrador</button><button class="button" id="publish" ${state.role!=='admin'?'disabled':''}>Publicar</button></div></header><p id="admin-status" role="status" aria-live="polite"></p><div id="admin-view">${editor()||'<p>Cargando…</p>'}</div></div></div>`;
 $$('details',$('#admin-panel')).forEach(element=>{if(opened.has($('summary',element)?.textContent))element.open=true;});
 loadTab().catch(error=>status(error.message,true));
}
async function loadTab(){
 const view=$('#admin-view'),requestedTab=tab;
 if(tab==='leads'||tab==='reviews'){
  const rows=await api('submissions',{kind:tab==='reviews'?'review':'contact',offset});if(tab!==requestedTab)return;
  view.innerHTML=`<div class="admin-records">${rows.length?rows.map(r=>{const p=r.payload;return `<article class="admin-record"><div class="module-heading"><h3>${e(p.name)}</h3><time>${e(new Date(r.created_at).toLocaleString('es-MX'))}</time></div><p>${e(p.email)} · ${e(p.phone||'Sin teléfono')}</p><p><strong>${e(p.interest)}</strong> · Aviso por correo: ${e(r.email_status)}</p><p class="record-message">${e(p.message)}</p>${p.project?`<dl>${Object.entries(p.project).filter(([,v])=>v).map(([k,v])=>`<dt>${e({zone:'Zona',property_type:'Tipo',budget:'Presupuesto',timeframe:'Plazo',contact_preference:'Contacto preferido',property_id:'Propiedad',page:'Página'}[k]||k)}</dt><dd>${e(v)}</dd>`).join('')}</dl>`:''}${tab==='leads'?`<label>Seguimiento<select data-followup="${e(r.id)}" ${state.role!=='admin'?'disabled':''}>${Object.entries({new:'Nuevo',contacted:'Contactado',in_progress:'En proceso',closed:'Cerrado',archived:'Archivado'}).map(([v,l])=>`<option value="${v}" ${r.followup===v?'selected':''}>${l}</option>`).join('')}</select></label>`:`<p>Calificación: ${e(p.rating)}/5 · Publicación autorizada: ${p.publishConsent?'Sí':'No'} · Estado: ${e(r.moderation_status)}</p><div class="admin-actions"><button class="button button-outline" data-moderate="${r.id}" data-status="approved" ${!p.publishConsent||state.role!=='admin'?'disabled':''}>Aprobar</button><button class="text-button" data-moderate="${r.id}" data-status="pending" ${state.role!=='admin'?'disabled':''}>Pendiente</button><button class="text-button" data-moderate="${r.id}" data-status="rejected" ${state.role!=='admin'?'disabled':''}>Rechazar</button></div>${!p.publishConsent?'<small>Sin permiso de publicación. No se puede aprobar.</small>':''}`}</article>`;}).join(''):'<p>Todavía no hay registros en esta página.</p>'}</div><div class="admin-actions"><button class="text-button" data-offset="${Math.max(0,offset-50)}" ${offset===0?'disabled':''}>Anteriores</button><span>Registros ${offset+1}–${offset+rows.length}</span><button class="text-button" data-offset="${offset+50}" ${rows.length<50?'disabled':''}>Siguientes</button></div>`;
 }
 if(tab==='inventory'){
  view.innerHTML='<p>Todas las propiedades activas del equipo aparecen automáticamente, más un máximo de 10 selecciones externas de KW. Al salir del inventario activo pasan a vendidas o rentadas; marca abajo las canceladas para ocultarlas. No se modifica el registro de KW Premier.</p><form method="post" id="inventory-search"><label>Buscar propiedades publicadas<input name="query" type="search" maxlength="100" placeholder="Título, colonia, municipio o asesor"></label><button class="button button-outline">Buscar</button></form><div id="inventory-results"></div><section><h2>Historial de operaciones</h2><p>Las canceladas quedan ocultas. Si una propiedad vuelve a estar activa, también deja de aparecer en el historial público.</p><div id="history-results"></div></section>';
  const rows=await api('history');if(tab!==requestedTab)return;renderHistory(rows);
 }
 if(tab==='media')view.innerHTML=block('Imágenes públicas del sitio','<p>Sube una imagen JPG, PNG o WebP de hasta 3 MB. Copia su URL al campo de portada, fotografía o imagen del módulo correspondiente.</p><form method="post" id="upload-form"><label>Seleccionar imagen<input type="file" name="image" accept="image/jpeg,image/png,image/webp" required></label><button class="button button-outline">Subir imagen</button></form><div id="upload-result"></div>');
 if(tab==='settings')view.innerHTML=block('Recepción de formularios',`<p>Dirección actual: <strong>${e(state.settings.notification_email)}</strong>. Los envíos de prueba permanecen en Dani hasta que se cambie aquí.</p><form method="post" id="settings-form"><label>Correo que recibirá los avisos<input name="email" type="email" required value="${e(state.settings.notification_email)}"></label><button class="button" ${state.role!=='admin'?'disabled':''}>Guardar destinatario</button></form><p>Inventario automático: ID KW ${e(state.settings.inventory_advisor_id)}.</p>`);
 if(tab==='versions')view.innerHTML=block('Publicaciones anteriores',`<p>Restaurar recupera una versión en el borrador. Revísala antes de publicarla.</p>${state.versions.length?state.versions.map(v=>`<div class="version-row"><span>Versión ${e(v.id)} · ${e(new Date(v.created_at).toLocaleString('es-MX'))}</span><button class="text-button" data-restore="${e(v.id)}">Restaurar en borrador</button></div>`).join(''):'<p>El historial aparecerá después de la primera publicación desde el panel.</p>'}`);
}
function renderHistory(rows){
 const container=$('#history-results');if(!container)return;
 container.innerHTML=rows.length?rows.map(row=>`<article class="admin-record"><h3>${e(row.title)}</h3><p>${e(row.location)} · ${row.cancelled?'Cancelada · oculta':row.status==='rentada'?'RENTADA':'VENDIDA'}</p><button type="button" class="button button-outline" data-history="${e(row.property_id)}" data-cancelled="${!row.cancelled}" ${state.role!=='admin'?'disabled':''}>${row.cancelled?'Volver a mostrar en el historial':'Marcar cancelada y ocultar'}</button></article>`).join(''):'<p>Todavía no hay operaciones en el historial.</p>';
}
async function bootstrap(){state=await api('bootstrap');draft=editorialContent(state.draft);unsaved=false;shell();}
async function save(){collect();validateContent(draft);const result=await api('save',{content:draft,revision:state.revision});state.revision=result.revision;unsaved=false;$('#revision').textContent='Borrador guardado · versión '+state.revision;status('Borrador guardado. Los cambios todavía no son públicos.');}
async function withPending(fn){if(pending)return;pending=true;$('#admin-panel').setAttribute('aria-busy','true');try{await fn();}catch(error){status(error.message,true);}finally{pending=false;$('#admin-panel').removeAttribute('aria-busy');}}
document.addEventListener('input',ev=>{if(ev.target.matches('[data-bind]')){unsaved=true;$('#revision').textContent='Cambios sin guardar';}});
$('#admin-panel').addEventListener('click',ev=>{const b=ev.target.closest('button');if(!b)return;
 if(b.dataset.tab){collect();tab=b.dataset.tab;offset=0;shell();return;}
 if(b.id==='logout'){withPending(async()=>{await fetch(base+'/auth/v1/logout?scope=local',{method:'POST',headers:{apikey:config.publishableKey,Authorization:'Bearer '+session.access_token}}).catch(()=>{});session=null;persist();localStorage.removeItem('confort4-preview');location.reload();});return;}
 if(b.id==='save')withPending(save);
 if(b.id==='preview'){collect();try{validateContent(draft);localStorage.setItem('confort4-preview',JSON.stringify(draft));const route={team:'quienes-somos',vender:'vender',rentar:'rentar',comprar:'comprar',inventory:'propiedades',reviews:'resena',services:'vender',posts:'blog',checklists:'recursos',faq:'preguntas'}[tab]||'index';window.open(route+'.html?preview=1','_blank','noopener');status('Vista previa abierta. No se ha publicado.');}catch(error){status(error.message,true);}}
 if(b.id==='publish')withPending(async()=>{await save();if(!window.confirm('¿Publicar este borrador de Confort4? Los visitantes verán los cambios al recargar.'))return;const result=await api('publish',{revision:state.revision});state.revision=result.revision;const latest=await api('bootstrap');state.versions=latest.versions;$('#revision').textContent='Publicado · versión '+state.revision;status('Publicado. La página pública ya puede leer esta versión.');});
 if(b.dataset.move!==undefined){collect();const i=Number(b.dataset.move),j=i+Number(b.dataset.dir);[draft.home.modules[i],draft.home.modules[j]]=[draft.home.modules[j],draft.home.modules[i]];unsaved=true;shell();}
 if(b.dataset.removeModule){collect();draft.home.modules=draft.home.modules.filter(m=>m!==b.dataset.removeModule);unsaved=true;shell();}
 if(b.hasAttribute('data-new-post')){collect();draft.posts.push({slug:'nuevo-articulo-'+Date.now(),title:'Nuevo artículo',category:'Guías',excerpt:'',cover:'assets/home-detail.jpg',author:'Equipo Confort4',updated:new Date().toISOString().slice(0,10),published:false,summary:[],sections:[{title:'Primera sección',text:''}],source:{label:'',url:''}});unsaved=true;shell();}
 if(b.dataset.deletePost!==undefined&&window.confirm('¿Eliminar este artículo del borrador?')){collect();draft.posts.splice(Number(b.dataset.deletePost),1);unsaved=true;shell();}
 if(b.dataset.newSection!==undefined){collect();draft.posts[Number(b.dataset.newSection)].sections.push({title:'Nueva sección',text:''});unsaved=true;shell();}
 if(b.dataset.deleteSection!==undefined){collect();const [i,j]=b.dataset.deleteSection.split(',').map(Number);draft.posts[i].sections.splice(j,1);unsaved=true;shell();}
 if(b.hasAttribute('data-new-faq')){collect();draft.faq.push({category:'Proceso',question:'Nueva pregunta',answer:''});unsaved=true;shell();}
 if(b.dataset.deleteFaq!==undefined){collect();draft.faq.splice(Number(b.dataset.deleteFaq),1);unsaved=true;shell();}
 if(b.dataset.addPhoto){collect();const limits={'clients.items':100,'team.gallery':8,'team.nationalAward.photos':2},path=b.dataset.addPhoto;if(!limits[path])return;const rows=at(path);if(rows.length>=limits[path]){status('Has alcanzado el límite de fotos.',true);return;}rows.push(path==='clients.items'?{id:crypto.randomUUID(),photo:'',alt:'',caption:'',published:true}:{photo:'',caption:''});unsaved=true;shell();}
 if(b.dataset.deletePhoto){collect();if(!['clients.items','team.gallery','team.nationalAward.photos'].includes(b.dataset.deletePhoto))return;at(b.dataset.deletePhoto).splice(Number(b.dataset.index),1);unsaved=true;shell();}
 if(b.dataset.moderate)withPending(async()=>{await api('moderate',{id:b.dataset.moderate,status:b.dataset.status});await loadTab();status('Estado de reseña actualizado.');});
 if(b.dataset.history)withPending(async()=>{const cancelled=b.dataset.cancelled==='true';renderHistory(await api('history',{id:b.dataset.history,cancelled}));status(cancelled?'Operación cancelada: oculta del historial público.':'Operación restaurada en el historial.');});
 if(b.dataset.offset!==undefined){offset=Number(b.dataset.offset);loadTab().catch(error=>status(error.message,true));}
 if(b.dataset.restore)withPending(async()=>{if(!window.confirm('¿Reemplazar el borrador por esta versión anterior?'))return;await api('restore',{id:b.dataset.restore,revision:state.revision});await bootstrap();status('Versión restaurada en borrador. Aún no se ha publicado.');});
});
$('#admin-panel').addEventListener('change',ev=>{const el=ev.target;if(el.id==='add-module'&&el.value){collect();draft.home.modules.push(el.value);unsaved=true;shell();}if(el.dataset.moduleVisible){collect();draft.home.hiddenModules=draft.home.hiddenModules.filter(id=>id!==el.dataset.moduleVisible);if(!el.checked)draft.home.hiddenModules.push(el.dataset.moduleVisible);unsaved=true;$('#revision').textContent='Cambios sin guardar';}if(el.dataset.teamVisible){collect();draft.team.hiddenSections=draft.team.hiddenSections.filter(id=>id!==el.dataset.teamVisible);if(!el.checked)draft.team.hiddenSections.push(el.dataset.teamVisible);unsaved=true;$('#revision').textContent='Cambios sin guardar';}if(el.dataset.uploadPath)withPending(async()=>{collect();const result=await uploadImage(el.files[0]);set(el.dataset.uploadPath,result.url);unsaved=true;shell();status('Imagen lista en el borrador. Guarda y publica para mostrarla.');});if(el.dataset.followup)withPending(async()=>{await api('followup',{id:el.dataset.followup,status:el.value});status('Seguimiento actualizado.');});if(el.dataset.selection)withPending(async()=>{await api('select_property',{id:el.dataset.selection,selected:el.checked});status('Selección de propiedades actualizada.');});});
async function uploadImage(file){
 if(!file||file.size>3000000||!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('Selecciona JPG, PNG o WebP de hasta 3 MB.');
 const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file);});
 return api('upload',{mime:file.type,data});
}
$('#admin-panel').addEventListener('submit',ev=>{ev.preventDefault();const form=ev.target;withPending(async()=>{
 if(form.id==='inventory-search'){const rows=await api('inventory',{query:form.elements.query.value});$('#inventory-results').innerHTML=rows.map(p=>`<article class="admin-record"><h3>${e(p.titulo)}</h3><p>${e([p.colonia,p.municipio,p.asesor_nombre].filter(Boolean).join(' · '))}</p><p>${e(money(p.precio,p.moneda))} · ${e(p.operacion)}</p><label class="consent"><input type="checkbox" data-selection="${e(p.id)}" ${p.selected?'checked':''} ${state.role!=='admin'?'disabled':''}><span>Incluir como selección adicional</span></label></article>`).join('')||'<p>No hay coincidencias publicadas.</p>';}
 if(form.id==='settings-form'){const email=form.elements.email.value;if(!window.confirm('¿Enviar los próximos avisos de Confort4 a '+email+'?'))return;await api('settings',{email});state.settings.notification_email=email;status('Destinatario actualizado.');}
 if(form.id==='upload-form'){const file=form.elements.image.files[0];if(!file||file.size>3000000||!['image/jpeg','image/png','image/webp'].includes(file.type))throw Error('Selecciona JPG, PNG o WebP de hasta 3 MB.');status('Subiendo imagen…');const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(String(reader.result).split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file);});const result=await api('upload',{mime:file.type,data});$('#upload-result').innerHTML=`<label>URL de la imagen<input readonly value="${e(result.url)}" aria-label="URL para copiar"></label><img class="upload-preview" src="${safeURL(result.url)}" alt="Imagen subida">`;status('Imagen subida. Copia la URL y úsala en el contenido.');}
 });});
$('#login-form').addEventListener('submit',async ev=>{ev.preventDefault();const form=ev.target,button=$('button',form);button.disabled=true;status('Validando tu acceso…');try{const response=await fetch(endpoint,{method:'POST',headers:{apikey:config.publishableKey,Authorization:'Bearer '+config.anonKey,'Content-Type':'application/json'},body:JSON.stringify({action:'login',args:{username:form.elements.username.value,password:form.elements.password.value}}),signal:AbortSignal.timeout(20000)});const result=await response.json();if(!response.ok)throw Error(result.error||'No pudimos validar tu acceso.');session=normalizedSession(result);form.elements.password.value='';persist();await bootstrap();}catch(error){status(error.message,true);if(['mfa_required','mfa_enrollment_required'].includes(error.code))await mfa();}finally{button.disabled=false;}});
async function mfa(){
 try{const res=await fetch(base+'/auth/v1/user',{headers:{apikey:config.publishableKey,Authorization:'Bearer '+session.access_token}});const user=await res.json();let factor=user.factors?.find(f=>f.status==='verified'&&f.factor_type==='totp');let enrollment=null;
 if(!factor){for(const pendingFactor of user.factors||[]){if(pendingFactor.status!=='verified'&&pendingFactor.friendly_name==='Confort4 editor')await auth('factors/'+pendingFactor.id,{},session.access_token,'DELETE');}enrollment=await auth('factors',{factor_type:'totp',friendly_name:'Confort4 editor'},session.access_token);factor={id:enrollment.id};}
 $('#login-form').hidden=true;let form=$('#mfa-form');if(!form){form=document.createElement('form');form.id='mfa-form';form.className='site-form';$('#login-form').after(form);}form.innerHTML='<div class="mfa-setup"></div><label>Código de tu aplicación de autenticación<input name="code" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" required></label><button class="button">Verificar acceso</button><p role="status"></p>';if(enrollment){const setup=$('.mfa-setup',form);const intro=document.createElement('p');intro.textContent='Escanea este QR con tu aplicación de autenticación. Necesitarás el código para entrar al editor.';const image=document.createElement('img');image.alt='QR para configurar verificación en dos pasos';const qr=enrollment.totp.qr_code;image.src=/^data:image\/(?:png|svg\+xml)[;,]/.test(qr)?qr:'data:image/svg+xml;base64,'+btoa(unescape(encodeURIComponent(qr)));const secret=document.createElement('code');secret.textContent=enrollment.totp.secret;setup.append(intro,image,secret);}form.onsubmit=async ev=>{ev.preventDefault();$('button',form).disabled=true;try{const challenge=await auth('factors/'+factor.id+'/challenge',{},session.access_token);const verified=await auth('factors/'+factor.id+'/verify',{challenge_id:challenge.id,code:form.elements.code.value},session.access_token);session={...session,...verified,expires_at:verified.expires_at||Math.floor(Date.now()/1000)+verified.expires_in};persist();await bootstrap();}catch(error){$('[role=status]',form).textContent=error.message;}finally{$('button',form).disabled=false;}};
 }catch{status('No se pudo iniciar la verificación de tu cuenta. Recarga e intenta de nuevo.',true);}
}
let lastActivity=Date.now();
for(const event of ['pointerdown','keydown','touchstart'])window.addEventListener(event,()=>{lastActivity=Date.now();},{passive:true});
window.setInterval(()=>{if(session&&Date.now()-lastActivity>20*60*1000){const token=session.access_token;session=null;persist();localStorage.removeItem('confort4-preview');fetch(base+'/auth/v1/logout?scope=local',{method:'POST',headers:{apikey:config.publishableKey,Authorization:'Bearer '+token}}).catch(()=>{});unsaved=false;location.reload();}},30000);
if(window.top!==window.self){document.body.textContent='Abre el editor directamente en su URL.';throw Error('Embedded editor blocked');}
window.addEventListener('beforeunload',ev=>{if(unsaved){ev.preventDefault();ev.returnValue='';}});
if(session)bootstrap().catch(error=>{status(error.message,true);if(['mfa_required','mfa_enrollment_required'].includes(error.code))mfa();});
